import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        int[] u = new int[2000007];
        int ans = 1;
        int mod = 1000000007;
        int i = 1;
        if (k == 1) {
            i = 0;
        }
        for (; i < p; i++) {
            if (u[i] == 0) {
                dfs(i, p, k, u);
                ans = (int)((long)ans * p % mod);
            }
        }
        System.out.println(ans);
        sc.close();
    }

    private static void dfs(int v, int p, int k, int[] u) {
        u[v] = 1;
        int x = (int)((long)k * v % p);
        if (u[x] == 0) {
            dfs(x, p, k, u);
        }
    }
}
